# Generated by Phase: IMPLEMENT | Feature: EVOL-053
"""Test-case traceability (EVOL-053): one machine-readable home for the case → test link, ratcheted.

config      `config/quality.json → traceability`: `home` {kind, pattern} — the ONE place a test states the case it
            proves: `pytest-marker` (the `case` marker on a test, a class or a module's `pytestmark`, read from the
            syntax tree — a marker in a comment or a docstring is text, not a marker); `title-tag` (`[FEATURE/CASE]`
            opening the literal title of a `test(` / `it(` / `t.Run(` call at the start of a line; `.only`, `.concurrent`,
            `.each(...)` allowed; `skip` / `todo` / `xit` and a `describe` link nothing — a suite title or a skipped test
            proves no case); `junit-displayname` (`@DisplayName("[FEATURE/CASE] …")`); or `custom` with a regex carrying
            a named group `id`, matched per line. `id_pattern` — the case grammar (the id part; the feature is the plan
            folder, `docs/spec/{FEATURE}/test_plan.md`, so a link is always `FEATURE/CASE`); `plans` — the glob of the
            plans; `test_roots` — root-anchored globs of the test files; `suffixes` — the file kinds scanned (a default
            list; `custom` scans every text file under the roots); `baseline` — the shrink-only debt file. `required:
            false` + `reason` for a repo with no plans (this framework: its tests are the T2 suites). The key absent =
            RED, never a fault.
files       tracked and untracked-not-ignored, existing on disk — the static round runs before `git add`.
declared    every case a plan declares: the first cell of a row in a table whose header starts with `ID`, outside code
            fences, qualified by the plan's feature; a `Tool` column whose cell begins with `Manual` marks a MANUAL case
            (never owed a test, reported as such); a duplicate id, or a first cell of an ID table that fails the
            grammar, is red. A plan glob that matches nothing while a `test_plan.md` exists elsewhere is red.
links       every link under the test roots at the home, with its file:line. A link naming no declared case is red (as
            wrong as a case with no test); a malformed id is red; a test file the home cannot parse is red.
check       case → test, never test → case: every declared, non-manual case has a linking test, or sits in the baseline.
            The baseline may only shrink: an entry now linked is red until removed; an entry naming no declared case
            is red; a baseline on disk that git does not track is red (commit it — CI reads the commit).
baseline    `--init` records the unlinked set once (refused when the file exists, and refused when no case links at
            all — a home or a root that matches nothing is a misconfiguration, not debt); `--refresh` removes entries
            that are linked or gone — never adds.
"""
from __future__ import annotations

import ast
import json
import re
import subprocess
from pathlib import Path

from .common import GateFault, key
from .seal import _norm_path, _root_match

HOMES = {
    "pytest-marker": None,   # read from the syntax tree, never a regex
    "title-tag": r'^[ \t]*(?:(?:const|let|var)\s+\w+\s*=\s*)?(?:test|it|t\.Run)(?:\.(?:only|concurrent|each\([^)\n]*\)))*\s*\(\s*["\'`]\[(?P<id>[^\]\n]*)\]',
    "junit-displayname": r'^[ \t]*@DisplayName\(\s*"\[(?P<id>[^\]\n]*)\]',
}
DEFAULT_ID = r"^(?:AC|TC-API|TC|REL-[A-Z]+|UX|A11Y|BRAND|LAYOUT)-\d{2,}$"
FEATURE = re.compile(r"^[A-Z][A-Z0-9]*-[0-9A-Z]+(?:-[0-9A-Z]+)*$")
DEFAULT_SUFFIXES = [".py", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".go", ".rs", ".java", ".kt", ".rb", ".php", ".cs", ".swift", ".scala", ".dart", ".ex", ".exs"]
NOT_A_PROOF = {"skip", "skipif", "xfail"}
LINK_CELL = re.compile(r"^\[([^\]]+)\]\([^)]*\)$")


def cfg(repo: Path) -> dict:
    t = key(repo, "traceability", default=None)
    if not isinstance(t, dict):
        raise GateFault("config key `traceability` is missing from config/quality.json — the home of the case → test link, its grammar, the plans, the test roots and the baseline live there (SETUP materialises it; SETUP --upgrade adds it)")
    required = t.get("required", True)
    if not isinstance(required, bool):
        raise GateFault("traceability.required must be true or false")
    out = {"required": required, "reason": str(t.get("reason") or "")}
    if not required:
        return out
    home = t.get("home") if isinstance(t.get("home"), dict) else {}
    kind = str(home.get("kind") or "")
    if kind == "custom" and not home.get("pattern"):
        raise GateFault("traceability.home.kind `custom` needs a `pattern` (a regex with a named group `id`, matched per line)")
    if kind not in HOMES and kind != "custom":
        raise GateFault(f"traceability.home.kind `{kind or '(none)'}` is not one of {', '.join(HOMES)}, custom — the home is the one place a test states its case")
    rx = None
    pattern = home.get("pattern") or HOMES.get(kind)
    if pattern:
        try:
            rx = re.compile(str(pattern), re.M)
        except re.error as e:
            raise GateFault(f"traceability.home.pattern is not a regex: {e}") from None
        if "id" not in rx.groupindex:
            raise GateFault("traceability.home.pattern must carry a named group `id`")
    try:
        idrx = re.compile(str(t.get("id_pattern") or DEFAULT_ID))
    except re.error as e:
        raise GateFault(f"traceability.id_pattern is not a regex: {e}") from None
    roots = t.get("test_roots", ["tests/**", "e2e/**"])
    if not isinstance(roots, list) or not roots or not all(isinstance(x, str) for x in roots):
        raise GateFault("traceability.test_roots must be a non-empty list of globs")
    suffixes = t.get("suffixes", DEFAULT_SUFFIXES)
    if not isinstance(suffixes, list) or not all(isinstance(x, str) for x in suffixes):
        raise GateFault("traceability.suffixes must be a list of file suffixes")
    base = _norm_path(str(t.get("baseline") or "docs/project_log/traceability_baseline.json"))
    if base.startswith("/") or ".." in base.split("/"):
        raise GateFault(f"traceability.baseline `{base}` must be a path inside the repository")
    out.update({"kind": kind, "home": rx, "id": idrx, "plans": str(t.get("plans") or "docs/spec/*/test_plan.md"), "roots": roots,
                "suffixes": [".py"] if kind == "pytest-marker" else suffixes, "any_suffix": kind == "custom", "baseline": base})
    return out


# ─── files: the tree on disk ────────────────────────────────────────────────────

def _git(repo: Path, *args) -> str:
    try:
        r = subprocess.run(["git", "-C", str(repo), "-c", "core.quotepath=false", *args], capture_output=True, text=True, timeout=120)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise GateFault(f"git {' '.join(args)} could not run: {e}") from None
    if r.returncode != 0:
        raise GateFault(f"git {' '.join(args)} failed: {(r.stderr.strip().splitlines() or ['(no message)'])[-1]}")
    return r.stdout


def files(repo: Path) -> list[str]:
    """Tracked and untracked-not-ignored paths that exist on disk — what the next commit carries."""
    names = set(_git(repo, "ls-files").splitlines()) | set(_git(repo, "ls-files", "--others", "--exclude-standard").splitlines())
    return sorted(_norm_path(n) for n in names if n and (repo / n).is_file())


def is_tracked(repo: Path, rel: str) -> bool:
    return rel in set(_git(repo, "ls-files", "--", rel).splitlines())


# ─── declared cases ─────────────────────────────────────────────────────────────

def _cell(raw: str) -> str:
    c = raw.strip().strip("`*").strip()
    m = LINK_CELL.match(c)
    return (m.group(1) if m else c).strip("`*").strip()


def declared(repo: Path, c: dict, listing: list[str] | None = None) -> tuple[dict[str, dict], list[dict]]:
    """qualified id → {at, manual}; findings (a folder that is not a feature, a duplicate, a malformed id, a plan glob that matches nothing)."""
    listing = listing if listing is not None else files(repo)
    plans = [p for p in listing if _root_match(p, [c["plans"]])]
    out: dict[str, dict] = {}
    bad: list[dict] = []
    if not plans:
        others = [p for p in listing if p.endswith("test_plan.md")]
        if others:
            bad.append({"path": "config/quality.json", "reason": f"traceability.plans `{c['plans']}` matches nothing while a test plan exists at {others[0]} — the glob does not name the plans"})
        return out, bad
    for plan in plans:
        feature = Path(plan).parent.name
        if not FEATURE.match(feature):
            bad.append({"path": plan, "reason": f"plan folder `{feature}` is not a feature id — plans live at docs/spec/{{FEATURE}}/ (traceability.plans)"}); continue
        header: list[str] | None = None
        fence = False
        lines = (repo / plan).read_text(encoding="utf-8", errors="replace").splitlines()
        for n, line in enumerate(lines, 1):
            if line.lstrip().startswith(("```", "~~~")):
                fence = not fence; header = None; continue
            if fence:
                continue
            m = re.match(r"^\s*\|(.*)\|\s*$", line)
            if not m:
                header = None; continue
            cells = [_cell(x) for x in m.group(1).split("|")]
            if cells and all(set(x) <= set("-: ") for x in cells):
                continue   # the separator row keeps the header
            if header is None or (cells and cells[0].upper() == "ID"):
                header = [x.upper() for x in cells]; continue
            if not header or header[0] != "ID" or not cells or not cells[0]:
                continue   # a table that declares no cases
            cell = cells[0]
            tool_i = header.index("TOOL") if "TOOL" in header else -1
            manual = tool_i >= 0 and tool_i < len(cells) and cells[tool_i].lower().startswith("manual")
            qid = f"{feature}/{cell}"
            if not c["id"].match(cell):
                bad.append({"path": f"{plan}:{n}", "reason": f"`{cell}` in an ID table fails the grammar traceability.id_pattern"}); continue
            if qid in out:
                bad.append({"path": f"{plan}:{n}", "reason": f"`{qid}` is declared twice (first at {out[qid]['at']}) — one case, one row"}); continue
            out[qid] = {"at": f"{plan}:{n}", "manual": manual}
    return out, bad


# ─── links at the home ──────────────────────────────────────────────────────────

def _marker_name(dec: ast.AST) -> tuple[str | None, list[str]]:
    """`pytest.mark.case("X")` / `mark.case("X")` → ("case", ["X"]); a bare `pytest.mark.skip` → ("skip", [])."""
    node = dec.func if isinstance(dec, ast.Call) else dec
    if not isinstance(node, ast.Attribute):
        return None, []
    chain = []
    while isinstance(node, ast.Attribute):
        chain.append(node.attr); node = node.value
    chain.append(getattr(node, "id", ""))
    chain.reverse()
    if len(chain) < 2 or chain[-2] != "mark":
        return None, []
    args = [a.value for a in getattr(dec, "args", []) if isinstance(a, ast.Constant) and isinstance(a.value, str)] if isinstance(dec, ast.Call) else []
    return chain[-1], args


def _pytest_links(text: str, rel: str, out: dict[str, list[str]], bad: list[dict], c: dict) -> None:
    try:
        tree = ast.parse(text)
    except SyntaxError as e:
        bad.append({"path": f"{rel}:{e.lineno or 1}", "reason": "the test file does not parse — its markers cannot be read"}); return

    def take(node: ast.AST, decorators: list[ast.AST], line: int) -> None:
        names = [(_marker_name(d), d) for d in decorators]
        cases = [(a, d) for (n, args), d in names for a in args if n == "case"]
        if any(n in NOT_A_PROOF for (n, _), _ in names):
            return   # a skipped or expected-to-fail test proves no case
        for a, d in cases:
            _record(a, f"{rel}:{getattr(d, 'lineno', line)}", out, bad, c)

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            take(node, node.decorator_list, node.lineno)
        elif isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "pytestmark" for t in node.targets):
            vals = node.value.elts if isinstance(node.value, (ast.List, ast.Tuple)) else [node.value]
            take(node, list(vals), node.lineno)
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "param":
            for kw in node.keywords:
                if kw.arg == "marks":
                    vals = kw.value.elts if isinstance(kw.value, (ast.List, ast.Tuple)) else [kw.value]
                    take(node, list(vals), node.lineno)


def _record(raw: str, where: str, out: dict[str, list[str]], bad: list[dict], c: dict) -> None:
    raw = raw.strip()
    feat, _, case = raw.partition("/")
    if not (feat and case) or not FEATURE.match(feat) or not c["id"].match(case):
        bad.append({"path": where, "reason": f"`{raw}` is not a case link — the form is FEATURE/CASE (e.g. FEAT-001/TC-01) with CASE matching traceability.id_pattern"}); return
    out.setdefault(f"{feat}/{case}", []).append(where)


def links(repo: Path, c: dict, listing: list[str] | None = None) -> tuple[dict[str, list[str]], list[dict]]:
    """qualified id → [file:line]; findings (malformed links, unparseable test files)."""
    listing = listing if listing is not None else files(repo)
    out: dict[str, list[str]] = {}
    bad: list[dict] = []
    for p in listing:
        if not _root_match(p, c["roots"]) or Path(p).name.startswith("conftest"):
            continue   # a conftest holds fixtures and the plugin itself, never a test that proves a case
        if not c["any_suffix"] and Path(p).suffix not in c["suffixes"]:
            continue
        try:
            text = (repo / p).read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue   # a binary under the roots is not a test file
        if c["kind"] == "pytest-marker":
            _pytest_links(text, p, out, bad, c); continue
        for m in c["home"].finditer(text):
            _record(m.group("id"), f"{p}:{text.count(chr(10), 0, m.start()) + 1}", out, bad, c)
    return out, bad


# ─── the baseline and the check ─────────────────────────────────────────────────

def read_baseline(repo: Path, c: dict) -> list[str]:
    p = repo / c["baseline"]
    if not p.is_file():
        return []
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the baseline {c['baseline']} is unreadable ({e}) — fix or delete it and --baseline --init again") from None
    items = d.get("unlinked") if isinstance(d, dict) else d
    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise GateFault(f"the baseline {c['baseline']} must carry `unlinked`: a list of qualified case ids")
    return sorted(set(items))


def check(repo: Path) -> dict:
    try:
        c = cfg(repo)
    except GateFault as e:
        return {"ok": False, "required": True, "reason": str(e), "findings": [], "cases": []}
    if not c["required"]:
        if not c["reason"]:
            return {"ok": False, "required": True, "reason": "traceability.required is false without a `reason` — say why this repo declares no test plan (fail closed)", "findings": [], "cases": []}
        return {"ok": True, "required": False, "reason": c["reason"], "findings": [], "cases": []}
    listing = files(repo)
    dec, bad_dec = declared(repo, c, listing)
    lnk, bad_lnk = links(repo, c, listing)
    base = read_baseline(repo, c)
    findings = list(bad_dec) + list(bad_lnk)
    if (repo / c["baseline"]).is_file() and not is_tracked(repo, c["baseline"]):
        findings.append({"path": c["baseline"], "reason": "the baseline is on disk but git does not track it — commit it (CI reads the commit; an uncommitted baseline is a push that is green here and red there)"})
    for qid in sorted(set(lnk) - set(dec)):
        findings.append({"path": lnk[qid][0], "reason": f"`{qid}` names no case any plan declares — an unknown link is as wrong as a case with no test"})
    owed = sorted(q for q, d in dec.items() if not d["manual"])
    unlinked = [q for q in owed if q not in lnk]
    new_debt = [q for q in unlinked if q not in base]
    for q in new_debt:
        findings.append({"path": dec[q]["at"], "reason": f"`{q}` has no linking test (the home: {c['kind']}) and is not in the baseline — link it or it is red"})
    shrink = sorted(q for q in base if q in lnk and q in dec)
    for q in shrink:
        findings.append({"path": c["baseline"], "reason": f"`{q}` is linked now — the baseline only shrinks: remove it (gate.py traceability --baseline --refresh)"})
    stale = sorted(q for q in base if q not in dec)
    for q in stale:
        findings.append({"path": c["baseline"], "reason": f"`{q}` names no declared case any more — stale debt, remove it (gate.py traceability --baseline --refresh)"})
    def status(q):
        if dec[q]["manual"]:
            return "manual"
        return "linked" if q in lnk else ("unlinked-baseline" if q in base else "unlinked")
    cases = [{"id": q, "plan": dec[q]["at"], "tests": lnk.get(q, []), "status": status(q)} for q in sorted(dec)]
    n_lnk = sum(1 for q in owed if q in lnk)
    manual = sum(1 for d in dec.values() if d["manual"])
    reason = (f"{len(dec)} case(s) declared, {n_lnk} linked, {len(unlinked)} unlinked ({len([q for q in unlinked if q in base])} in the baseline)"
              + (f", {manual} manual" if manual else "")) if dec else "no test plan declares a case yet"
    return {"ok": not findings, "required": True, "home": c["kind"], "declared": len(dec), "linked": n_lnk, "manual": manual, "unlinked": unlinked, "baseline": base,
            "new_debt": new_debt, "shrink": shrink, "stale": stale, "unknown": sorted(set(lnk) - set(dec)), "findings": findings, "cases": cases, "reason": reason}


def baseline(repo: Path, init: bool = False, refresh: bool = False) -> dict:
    c = cfg(repo)
    if not c["required"]:
        raise GateFault(f"traceability is not required in this repo ({c['reason']}) — no baseline to write")
    p = repo / c["baseline"]
    listing = files(repo)
    dec, _ = declared(repo, c, listing)
    lnk, _ = links(repo, c, listing)
    owed = sorted(q for q, d in dec.items() if not d["manual"])
    unlinked = [q for q in owed if q not in lnk]
    if init:
        if p.is_file():
            raise GateFault(f"the baseline {c['baseline']} exists — it only shrinks (--refresh); delete it by decision if it must be re-taken")
        if owed and not lnk:
            raise GateFault(f"no test links any of the {len(owed)} declared case(s) — a home ({c['kind']}) or a root ({', '.join(c['roots'])}) that matches nothing is a misconfiguration, not debt; link one case first, then --init")
        items, removed = unlinked, []
    elif refresh:
        old = read_baseline(repo, c)
        items = [q for q in old if q in unlinked]
        removed = [q for q in old if q not in items]
    else:
        raise GateFault("--baseline needs --init (record the debt once) or --refresh (shrink it)")
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps({"_doc": "Test-case traceability baseline (EVOL-053): the cases unlinked at adoption. New cases must link; this list only shrinks (python3 scripts/gate.py traceability --baseline --refresh; re-run it after a merge). Commit this file: the push and CI read it.", "unlinked": items}, indent=2) + "\n", encoding="utf-8")
    return {"ok": True, "path": c["baseline"], "unlinked": items, "removed": removed, "note": "commit the baseline — CI reads the commit"}


def render(res: dict) -> str:
    if not res.get("required", True):
        return f"traceability: n/a — {res['reason']}"
    if res["ok"]:
        return f"traceability: ok — {res['reason']} (home: {res.get('home')})"
    lines = [f"traceability: RED — {res['reason']}"]
    for f in res["findings"][:20]:
        lines.append(f"  {f['path']}: {f['reason']}")
    if len(res["findings"]) > 20:
        lines.append(f"  … {len(res['findings']) - 20} more (--json keeps them all)")
    return "\n".join(lines)
